{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"small": [event("a", 1, True)],
              "large": [event(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_window_boundaries():
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 9) == 6
    assert flags_in_window([], 2) == 0


def test_parse_flags_whitespace_and_skipped_lines():
    lines = ["", "  \t  ", "   # comment,with,commas", " a , 2 , 1 ",
             " b, -1, 0 ", " c, 3,  "]
    assert parse_transcript_log(iter(lines)) == [event("a", 2, True),
                                                 event("b", -1, False),
                                                 event("c", 3, None)]


@pytest.mark.parametrize("bad", ["id,1", "id,1,0,extra", "id,nope,1", "id,1,yes"])
def test_parse_errors_include_original_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # comment", "valid,1,0", bad])


def test_dedupe_last_duplicate_id_wins_and_result_sorted():
    old = event("a", 1, True)
    replacement = event("a", 3, None)
    events = [old, event("z", 2, True), event("b", 2, False), replacement]
    assert dedupe_transcripts(events) == [events[2], events[1], replacement]
    assert dedupe_transcripts([]) == []


def test_daily_counts_include_empty_days_and_ignore_outside_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 2) == []


def test_summary_uses_calendar_days_and_three_decimal_pooled_rate():
    groups = {"a": [event("a", 1, True), event("b", 4, True)],
              "b": [event("c", 4, False)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_ties_empty_and_limit():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "a": [event("a", 1, True)], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []


def test_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [event("b", 1, False)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_requires_consecutive_positive_counts():
    assert longest_flag_streak([1, 2, 0, 1, -1, 1, 2, 3]) == 3
    assert longest_flag_streak([1, 0, 1]) == 1
    assert longest_flag_streak([-1, 0]) == 0
    assert longest_flag_streak([]) == 0
